package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "Ya Allah, dengan Engkau kami memasuki waktu pagi dan dengan Engkau kami memasuki waktu petang; dengan Engkau kami hidup dan dengan Engkau kami mati, dan kepada Engkaulah kebangkitan.", "Pada waktu pagi.", "Nabi ﷺ mengajar para Sahabat mengucap pagi dan petang ini."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "Ya Allah, dengan Engkau kami memasuki waktu petang dan dengan Engkau kami memasuki waktu pagi; dengan Engkau kami hidup dan dengan Engkau kami mati, dan kepada Engkaulah tempat kembali.", "Pada waktu petang.", "Nabi ﷺ mengajar para Sahabat mengucap pagi dan petang ini."),
        "dua_afiyah_morning" to DuaText("Meminta Afiyah", "Ya Allah, sesungguhnya aku memohon kepada-Mu ampunan dan kesejahteraan di dunia dan akhirat.", "Nabi ﷺ tidak pernah meninggalkan doa ini, pagi atau petang.", "Tiada siapa yang diberikan sesuatu yang lebih baik daripada kesejahteraan."),
        "dua_afini_fi_badani" to DuaText("Kesihatan Badan, Pendengaran dan Penglihatan", "Ya Allah, kurniakanlah kesejahteraan kepada tubuhku. Ya Allah, sehatkanlah pendengaranku. Ya Allah, berikanlah kesejahteraan pada penglihatanku. Tiada Tuhan selain Engkau.", "Tiga kali setiap pagi dan petang.", "Doa untuk kesihatan dan perlindungan deria."),
        "dua_ya_hayyu_aslih" to DuaText("Betulkan Semua Urusan Saya", "Wahai Yang Maha Hidup, wahai Pemelihara, dengan rahmat-Mu aku meminta pertolongan: perbaikilah segala urusanku dan jangan serahkan aku kepada diriku sendiri walau sekelip mata.", "Nabi ﷺ menasihati Fatimah (RA) untuk mengucapkannya pagi dan petang.", "Memohon pertolongan Allah dalam setiap perkara."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbih Juwayriyah (RA)", "Maha Suci Allah dan segala puji bagi-Nya — sebanyak makhluk-Nya, sebanyak yang diredhai-Nya, seberat Arasy-Nya dan seberat tinta kalimat-kalimat-Nya.", "Tiga kali pada waktu pagi - lebih berat daripada jam berzikir.", "Mengucapkan empat lafaz ini tiga kali lebih berat daripada zikir dari subuh hingga tengah hari."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "Ya Allah, limpahkanlah selawat ke atas Muhammad ﷺ dan keluarga Muhammad sebagaimana Engkau telah selawat ke atas Ibrahim (AS) dan keluarga Ibrahim; Engkau Maha Terpuji, Maha Mulia. Ya Allah, berkatilah Muhammad ﷺ dan keluarga Muhammad sebagaimana Engkau telah memberkati Ibrahim (AS) dan keluarga Ibrahim; Engkau Maha Terpuji, Maha Mulia.", "Selawat ke atas Nabi ﷺ dalam solat dan setiap masa.", "Sesiapa yang berselawat sekali, Allah akan menurunkan sepuluh rahmat kepadanya (Muslim 408)."),
        "dua_wudu_after" to DuaText("Selepas Wudhu", "Saya bersaksi bahawa tiada yang berhak disembah melainkan Allah semata-mata, tiada sekutu bagi-Nya, dan Muhammad ﷺ adalah hamba dan Rasul-Nya. Ya Allah, jadikanlah aku termasuk orang-orang yang bertaubat dan orang-orang yang mensucikan diri.", "Selepas selesai wuduk.", "Lapan pintu syurga dibukakan untuknya masuk melalui mana saja yang dia kehendaki."),
        "dua_wudu_before" to DuaText("Sebelum Wudhu", "Dengan nama Allah.", "Apabila memulakan wudhu.", "Tidak ada wudhuk (yang sempurna) bagi orang yang tidak menyebut nama Allah di atasnya."),
        "dua_istiftah" to DuaText("Doa Pembukaan (Sana)", "Maha Suci Engkau ya Allah, dan segala puji bagiMu. Terpujilah namaMu, agungkanlah keagunganMu, dan tiada tuhan selain Engkau.", "Pada permulaan solat, sejurus selepas takbir pembukaan.", "Doa pembukaan solat sunat."),
        "dua_ruku" to DuaText("Dalam Ruku", "Maha Suci Tuhanku Yang Maha Agung.", "Sekurang-kurangnya tiga kali dalam ruku.", "Sunnah tasbih ruku."),
        "dua_sujood" to DuaText("Di Sujood", "Maha Suci Tuhanku Yang Maha Tinggi.", "Sekurang-kurangnya tiga kali dalam sujud.", "Seorang hamba paling dekat dengan Tuhannya ketika dalam sujud (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Bangkit dari Ruku", "Allah mendengar orang yang memuji-Nya. Ya Tuhan kami, bagiMu segala pujian.", "Semasa bangkit dari ruku dan berdiri tegak.", "Sesiapa yang 'Rabbana wa lakal-hamd' bertepatan dengan malaikat, dosanya yang telah lalu diampuni."),
        "dua_between_sajdas" to DuaText("Antara Dua Sajda", "Tuhanku, ampunilah aku. Tuhanku, ampunilah aku.", "Semasa duduk di antara dua sujud.", "Doa sunnah duduk di antara sujud."),
        "dua_before_salam_four" to DuaText("Berlindung dari Empat Perkara (Sebelum Salam)", "Ya Allah, sesungguhnya aku berlindung kepada-Mu dari azab neraka jahannam, dari azab kubur, dari fitnah hidup dan mati, dan dari kejahatan fitnah al-Masih Palsu (Dajjal).", "Selepas tasyahud akhir dan selawat, sebelum salam.", "Nabi ﷺ memerintahkan berlindung dari empat perkara ini."),
        "dua_qunoot_witr" to DuaText("Qunoot dalam Witir", "Ya Allah, berilah aku petunjuk kepada orang-orang yang telah Engkau beri petunjuk, berilah kesejahteraan kepadaku di antara orang-orang yang telah Engkau anugerahkan kesejahteraan, masukkanlah aku ke dalam pemeliharaan-Mu di antara orang-orang yang telah Engkau lindungi, berkahilah aku dalam apa yang telah Engkau berikan, dan lindungilah aku dari kejahatan apa yang telah Engkau tetapkan. Engkau menetapkan dan tidak ada yang menetapkan terhadap-Mu, dan orang yang Engkau bersahabat tidak pernah dihina. Terpuji dan Maha Tinggi Engkau, Tuhan kami.", "Dalam solat witir — Nabi ﷺ mengajarkannya kepada Hasan ibn Ali (RA).", "Sunnah qunot witir. (Di kalangan Hanafi, 'Allahumma inna nasta'inuka' juga terkenal.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "Ya Allah, kami memohon pertolongan-Mu dan keampunan-Mu, kami beriman kepada-Mu dan bertawakal kepada-Mu, kami memuji-Mu dengan sebaik-baiknya, kami bersyukur kepada-Mu dan tidak mengingkari, dan kami meninggalkan sesiapa yang menderhaka kepada-Mu. Ya Allah, hanya kepadaMu kami menyembah, kepadaMu kami berdoa dan sujud, kepadaMu kami bersegera dan berusaha, kami mengharapkan rahmatMu dan takut akan azabMu; sesungguhnya azabMu akan sampai kepada orang-orang yang kafir.", "Dalam witir - amalan Hanafi.", "Diriwayatkan daripada Umar (RA) dalam qunoot."),
        "dua_sleep_aslamtu" to DuaText("Kata-kata Terakhir Sebelum Tidur", "Ya Allah, aku berserah diri kepadaMu, menyerahkan urusanku kepadaMu dan menyerahkan punggungku kepada perlindunganMu, kerana berharap kepadaMu dan takut kepadaMu. Tiada tempat berlindung dan tiada jalan keluar daripada-Mu melainkan kepada-Mu. Aku beriman kepada kitabMu yang Engkau turunkan dan kepada NabiMu yang Engkau utus.", "Selepas wudhu, berbaring di sebelah kanan - perkataan terakhir sebelum tidur.", "Jika dia mati pada malam itu, dia mati dalam keadaan fitrah (Islam)."),
        "dua_waking_night" to DuaText("Bangun Malam", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian, dan Dia Maha Kuasa atas segala sesuatu. Segala puji bagi Allah, Maha Suci Allah, tiada yang berhak disembah melainkan Allah, Allah Maha Besar, dan tiada daya dan kekuatan melainkan dengan Allah. Ya Allah, ampunilah aku.", "Semasa bangun pada waktu malam.", "Doanya dikabulkan, dan jika dia berwudhu dan solat, maka doanya diterima."),
        "dua_hamm_ibn_masud" to DuaText("Doa untuk Kesedihan (Ibn Mas'ud)", "Ya Allah, aku adalah hambaMu, anak hambaMu, anak hamba perempuanMu. Ubun-ubunku ada di tangan-Mu, perintah-Mu atasku terlaksana, dan ketetapan-Mu tentang aku adalah adil. Aku memohon kepada-Mu dengan setiap nama-Mu, yang dengannya Engkau namakan diri-Mu, atau diturunkan dalam kitab-Mu, atau diajarkan kepada sesiapa pun dari makhluk-Mu, atau disimpan dengan diri-Mu dalam pengetahuan yang ghaib - agar Engkau jadikan Al-Quran sebagai penyejuk hatiku, cahaya dadaku, menghilangkan kesedihanku dan perginya kegelisahanku.", "Dalam kesedihan dan kesusahan - Allah menggantikan kesedihan dengan kegembiraan.", "Allah menghilangkan kerisauan dan kesedihannya dan memberinya kegembiraan di tempatnya."),
        "dua_difficulty_sahl" to DuaText("Apabila Sesuatu Sukar", "Ya Allah, tiada yang mudah melainkan yang Engkau jadikan mudah, dan Engkau jadikan yang susah itu mudah jika Engkau kehendaki.", "Apabila sesuatu terasa sukar.", "Kemudahan dalam peperiksaan dan tugas yang sukar."),
        "dua_musibah" to DuaText("Apabila Musibah (Istirja)", "Kita milik Allah dan kepada-Nya kita kembali. Ya Allah, berikanlah pahala kepadaku dalam kesusahanku dan gantikanlah untukku dengan yang lebih baik.", "Atas sebarang kehilangan atau musibah.", "Allah pasti memberikan sesuatu yang lebih baik — Ummu Salamah (RA) diberikan kepada Nabi ﷺ."),
        "dua_debt" to DuaText("Untuk Pelepasan Hutang", "Ya Allah, cukupkanlah aku dengan apa yang Engkau halalkan terhadap apa yang Engkau haramkan, dan dengan karunia-Mu bebaskanlah aku dari selain-Mu.", "Untuk membayar hutang — diajar oleh Ali (RA).", "Walaupun hutang itu seperti gunung, Allah akan menyelesaikannya."),
        "dua_anger" to DuaText("Apabila Marah", "Aku berlindung kepada Allah dari syaitan yang terkutuk.", "Bila marah.", "Nabi ﷺ berkata: jika dia berkata demikian, kemarahannya akan hilang."),
        "dua_waswasa" to DuaText("Terhadap Waswasa dalam Iman", "Saya beriman kepada Allah dan Rasul-Nya.", "Apabila syaitan berbisik tentang iman datang.", "Apabila bisikan datang, katakan ini dan berhenti di sana (dan juga berlindung kepada Allah)."),
        "dua_travel_full" to DuaText("Permohonan Perjalanan Lengkap", "Ya Allah, kami memohon kepada-Mu dalam perjalanan ini kebaikan dan ketakwaan, dan amal yang Engkau ridhai. Ya Allah, permudahkanlah perjalanan kami ini dan pendekkanlah jaraknya. Ya Allah, Engkaulah peneman dalam perjalanan dan penjaga keluarga.", "Apabila memulakan perjalanan, selepas 'Subhanalladhi sakhkhara'.", "Doa perjalanan sunnah yang lengkap."),
        "dua_return_travel" to DuaText("Pulang dari Perjalanan", "Kita kembali, bertaubat, menyembah dan memuji Tuhan kita.", "Sekembalinya dari sebuah perjalanan.", "Nabi ﷺ berkata demikian semasa pulang dari sebuah perjalanan."),
        "dua_farewell_traveller" to DuaText("Mengucapkan Selamat Tinggal kepada Pengembara", "Aku serahkan kepada Allah agamamu, amanahmu dan kesudahan amalmu.", "Apabila mengucapkan selamat tinggal kepada pengembara.", "Apa yang dipertanggungjawabkan kepada Allah tidak pernah hilang."),
        "dua_entering_town" to DuaText("Berhenti di suatu Tempat", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari kejahatan makhluk-Nya.", "Apabila berhenti di sesuatu tempat atau tiba di bandar baru.", "Tidak ada yang akan membahayakannya sehingga dia pergi dari sana."),
        "dua_boarding_ship" to DuaText("Menaiki Kapal / Kenderaan", "Dengan nama Allah pelayarannya dan berlabuhnya. Sesungguhnya Tuhanku Maha Pengampun lagi Maha Penyayang.", "Ketika menaiki kapal atau kenderaan — sabda Nabi Nuh (AS).", "Sebuah ayat Al-Quran — doa bahtera Nuh (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar bersama Hayyul-Qayyum", "Aku memohon ampun kepada Allah yang tiada Tuhan selain Dia, Yang Hidup Kekal, Maha Pemelihara, dan aku bertaubat kepada-Nya.", "Untuk taubat.", "Dosanya diampuni walaupun dia telah melarikan diri dari medan perang."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Ya Tuhanku, ampunilah dan berilah rahmat, sesungguhnya Engkau adalah sebaik-baik penyayang.", "Doa Al-Quran - untuk keampunan dan rahmat.", "Ayat terakhir Surah al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Maha Suci Engkau ya Allah, dan segala puji bagiMu. Aku bersaksi bahawa tiada Tuhan selain Engkau. Aku memohon ampun kepada-Mu dan bertaubat kepada-Mu.", "Apabila bangun dari perhimpunan.", "Ia menjadi kafarat untuk sebarang kesalahan yang diperkatakan dalam perhimpunan itu."),
        "dua_jami_forgiveness" to DuaText("Pengampunan Menyeluruh", "Ya Allah, ampunilah kesalahanku, kejahilanku, kelebihanku dalam urusanku, dan segala yang Engkau lebih mengetahui daripadaku.", "Doa Nabi yang menyeluruh ﷺ.", "Nabi ﷺ pernah membuat doa ini."),
        "dua_parents_nuh" to DuaText("Doa Nuh (AS) untuk Ibu Bapa", "Ya Tuhanku, ampunilah aku, ibu bapaku, sesiapa yang masuk ke rumahku dalam keadaan beriman, dan semua orang yang beriman lelaki dan perempuan.", "Untuk ibu bapa dan orang-orang yang beriman.", "Doa Nabi Nuh (AS)."),
        "dua_shukr_parents" to DuaText("Syukur untuk Ibu Bapa & Anak yang Soleh", "Ya Tuhanku, berilah aku ilham untuk tetap mensyukuri nikmat-Mu yang telah Engkau anugerahkan kepadaku dan kepada dua orang ibu bapakku, dan untuk mengerjakan amal saleh yang Engkau ridhai, dan jadikanlah anak cucuku yang soleh. Aku bertaubat kepada-Mu dan aku termasuk orang-orang yang berserah diri.", "Doa al-Quran mencapai umur empat puluh tahun.", "Syukur, perbuatan baik dan soleh anak-anak seseorang - semuanya dalam satu doa."),
        "dua_intimacy" to DuaText("Sebelum Hubungan Perkahwinan", "Dengan nama Allah. Ya Allah, jauhkanlah syaitan dari kami dan jauhkanlah syaitan dari apa yang Engkau anugerahkan kepada kami.", "Sebelum hubungan suami isteri.", "Jika seorang anak ditakdirkan, syaitan tidak akan menyakitinya."),
        "dua_ibrahim_children_protection" to DuaText("Perlindungan Rumah dan Kanak-kanak", "Ya Tuhanku, jadikanlah negeri ini aman dan jauhkanlah aku beserta anak cucuku daripada menyembah berhala.", "Doa Nabi Ibrahim (AS) — untuk keselamatan kota dan anak-anaknya.", "Doa agar tetap teguh dalam tauhid."),
        "dua_drinking_milk" to DuaText("Apabila Minum Susu", "Ya Allah, berkatilah kami dan tambahkanlah kepada kami.", "Apabila minum susu.", "Susu mencukupi sebagai makanan dan minuman."),
        "dua_iftar_host" to DuaText("Ketika Berbuka Puasa Bersama Orang Lain", "Semoga orang yang berpuasa berbuka bersamamu, semoga orang yang soleh memakan makananmu, dan semoga para malaikat mendoakanmu.", "Ketika berbuka di rumah orang.", "Doa Nabi ﷺ untuk tuan rumah."),
    )
}
